function gutterCapacity(heights) {
    let water = 0;
    for (let i = 0; i < heights.length; i++) {
        let leftWall = 0;
        for (let j = 0; j <= i; j++)
            leftWall = Math.max(leftWall, heights[j]);
        let rightWall = 0;
        for (let j = i; j < heights.length; j++)
            rightWall = Math.max(rightWall, heights[j]);
        water += Math.min(leftWall, rightWall) - heights[i];
    }
    return water;
}

function gutterCapacity(heights) {
    const n = heights.length;
    const leftWall = new Array(n).fill(0);
    const rightWall = new Array(n).fill(0);
    for (let i = 0; i < n; i++)
        leftWall[i] = Math.max(i === 0 ? 0 : leftWall[i - 1], heights[i]);
    for (let i = n - 1; i >= 0; i--)
        rightWall[i] = Math.max(i === n - 1 ? 0 : rightWall[i + 1], heights[i]);
    let water = 0;
    for (let i = 0; i < n; i++)
        water += Math.min(leftWall[i], rightWall[i]) - heights[i];
    return water;
}

function gutterCapacity(heights) {
    let left = 0;
    let right = heights.length - 1;
    let leftWall = 0;
    let rightWall = 0;
    let water = 0;
    while (left < right) {
        if (heights[left] < heights[right]) {
            leftWall = Math.max(leftWall, heights[left]);
            water += leftWall - heights[left];
            left++;
        } else {
            rightWall = Math.max(rightWall, heights[right]);
            water += rightWall - heights[right];
            right--;
        }
    }
    return water;
}
